import styled, {css} from "styled-components";
import { ReactComponent as pencil } from "../../../assets/icons/pencil.svg"
import { ReactComponent as user } from "../../../assets/icons/user.svg"
import { ReactComponent as building } from "../../../assets/icons/building.svg"
import { ReactComponent as logout } from "../../../assets/icons/logOut.svg"

const iconStyle = css`
    width: 15px;
    height: 15px;
    transition: 0.3s ease all;

    path {
      fill: rgba(0, 0, 0, 0.2);
    }

    a:hover &,
        .active & {
    path {
      fill: blue;
    }
  }
`

const Container = styled.div`
    width: 250px;
    height: 100vh;
    box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);

    a {
        text-decoration: none;
    }

    .active div {
        background-color: rgba(0, 0, 0, 0.02);
        color: blue;
    }

    .active div div {
        path {
        fill: blue;
        }
    }

    .active div::before {       
        background-color: blue;
    }
`

const Content = styled.div`
    padding: 15px 10px;
    cursor: pointer;
    position: relative;
    color: black;
    display: flex;
    align-items: center;
    gap: 5px;
    transition: 0.3s ease color;

    &::before {
        content: "";
        position: absolute;
        left: 0;
        top: 0;
        width: 3px;
        height: 100%;
        background-color: transparent;
        transition: 0.3s ease background-color;
    }

    &:hover::before {
        background-color: blue;
    }

    &:hover {
        background-color: rgba(0, 0, 0, 0.02);
        color: blue;
    }
`

Content.Logout = styled.div`
     padding: 15px 10px;
     cursor: pointer;
     display: flex;
     align-items: center;
     gap: 5px;
    color: black;
     &:hover {
        background-color: rgba(0, 0, 0, 0.02);
        color: red;
    }
`

const IconWrapper = styled.div`
    height: 60px;
    display: flex;
    gap: 5px;
    justify-content: center;
    align-items: center;
    border-bottom: 1px solid rgba(0, 0, 0, 0.2);

    img {
        width: 40px;
        border-radius: 50%;
}
`

const Icons = styled.div``
Icons.Pencil = styled(pencil)`
  ${iconStyle}
`

Icons.User = styled(user)`
   ${iconStyle}
`
Icons.Building = styled(building)`
   ${iconStyle}
`

Icons.Logout = styled(logout)`
    width: 15px;
    height: 15px;
    transition: 0.3s ease all;

    path {
      fill: rgba(0, 0, 0, 0.2);
    }

    a:hover &,
        .active & {
    path {
      fill: red;
    }
  }
`

export { Container, Content, IconWrapper, Icons }