import React, { useEffect, useState } from 'react'
import { Container } from './style'
import HouseCard from '../HouseCard'
import { useLocation, useNavigate } from 'react-router-dom';
import useSearch from '../../hooks/useSearch';
import { useQuery, useQueryClient } from '@tanstack/react-query';


function Favourite() {
  // const [data, setdata] = useState([])
  const { search } = useLocation()
  const query = useSearch()
  const navigate = useNavigate()
  const queryClient = useQueryClient()

  const token = localStorage.getItem("token");

    const {isLoading, error, data} = useQuery({
      queryKey: ["favouriteHouses"],
      queryFn: () => fetch(`https://housing-backend-mhvy.onrender.com/api/houses/favouriteList`)
          .then(res => res.json())
    })

    const refreshData = () => {
      queryClient.invalidateQueries(["favouriteHouses"]);
    }
  

  const onSelect = (id) => {
    navigate(`/properties/${id}`)
  }  

  return (
    <>
      <div className="title" style={{marginTop:"50px"}}>Favourite</div>
      <div className="info" style={{textAlign:"center"}}>Nulla quis curabitur velit volutpat auctor bibendum consectetur sit.</div>
      <Container>
        {data? data?.map((value, index) => {
          return <HouseCard key={index} data={value} onClick={() => onSelect(value._id)} refreshData={refreshData} />
        }) : <h1>No data found</h1>}
      </Container>
    </>
  )
}

export default Favourite