import React, { useEffect, useState } from 'react'
import { Admin, AntTable, Ban, Button, Container, Content, Title, Trash } from './style'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'

function Users() {
  const queryClient = useQueryClient()
  const token = localStorage.getItem("token")

  const { data } = useQuery({
    queryKey: ["users"],
    queryFn: () =>
      fetch("https://housing-backend-mhvy.onrender.com/api/users")
        .then(res => res.json())
  })

  const users = data?data.filter(user => user.username != "admin" && user._id != localStorage.getItem("id")): []

  console.log(users);




  const { mutate } = useMutation({
    mutationFn: async (id) => {
      const res = await fetch(`https://housing-backend-mhvy.onrender.com/api/users/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`
        } 
      });

      if (!res.ok) {
        throw new Error("Foydalanuvchini o‘chirishda xatolik yuz berdi");
      }

      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["users"])
    }
  })
  const onDelete = (id) => {
    mutate(id)
  }

  const onBlock = (id) => {
    fetch(`https://housing-backend-mhvy.onrender.com/api/users/${id}/ban`, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`
      }
    })
      .then(res => res.json())
      .then(data => {
        queryClient.invalidateQueries(["users"])
    })
  }

  const toggleMakeAdmin = (id) => {
    fetch(`https://housing-backend-mhvy.onrender.com/api/users/make-admin/${id}`, {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${token}`
      }
    })
      .then(res => res.json())
      .then(data => {
        console.log(data);
        
        queryClient.invalidateQueries(["users"])
    })
  }

  const columns = [
    {
      title: "No",
      render: (data, record, index) => index + 1,
      key: "index"
    },
    {
      title: "Username",
      render: (data,) => data.username,
      key: "username"
    },
    {
      title: "Email",
      render: (data) => data.email,
      key: "eamil"
    },
    {
      title: "Actions",
      render: (data) => {
        return (
          <div style={{ display: "flex", gap: "10px" }}>
            <Button onClick={() => toggleMakeAdmin(data._id)} $color="#2196f3"><Admin />{data.isAdmin ? "Remove Admin" : "Make Admin"}</Button>
            <Button onClick={() => onBlock(data._id)} $color="#ff9800"><Ban />{data.isBanned ? "Unblock" : "Block"}</Button>
            <Button onClick={() => onDelete(data._id)} $color="red"><Trash />Delete</Button>
          </div>
        )
      },
      key: "actions",
      width: 350
    }
  ]

  return (
    <Container>
      <Title>Users</Title>
      <Content>
        <AntTable dataSource={users} columns={columns} />
      </Content>
    </Container>
  )
}

export default Users