import styled from "styled-components";

const Container = styled.div`
    width: 320px;
    height: 370px;
    border-radius: 10px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    position: relative;
    /* transition: 0.3s ease all; */
    box-shadow: 0 0 5px rgba(0, 0, 0, 0.15);
    /* &:hover {
        transform: scale(1.02);
    } */
`

const Banner = styled.div`
    min-width: 80px;
    max-width: 130px;
    height: 30px;
    background-image: linear-gradient(#34AADC, #00ffff);
    position: absolute;
    top: 0;
    right: 13px;
    border-radius: 0 0 8px 8px;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 5px;
    overflow-x: auto;
    color: #212529;

    &::-webkit-scrollbar {
        display: none;
    }
`

const Img = styled.img`
    width: 100%;
    height: 210px;
    object-fit: cover;
`

const Content = styled.div`
    width: 100%;
    height: 170px;
    /* border: 1px solid red; */
    border-radius: 12px;
    position: absolute;
    left: 0;
    bottom: 0;
    background-color: #F8F9FA;
    padding: 15px;
    color:#212529;
`

Content.Title = styled.div`
    font-size: 20px;
    font-weight: bold;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
`

Content.Text = styled.div`
    font-size: 14px;
    color: #666;
    margin: 10px 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
`

const Button = styled.button`
    padding: 8px 12px;
    font-size: 14px;
    font-weight: bold;
    border: none;
    background-color: red;
    color: white;
    border-radius: 5px;
    cursor: pointer;
    position: absolute;
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    transition: 0.3s ease background-color;
    /* margin: 0 auto; */
    
    &:active {
      transform: translateX(-50%) scale(0.95);
    }

    &:hover {
      background-color: darkred;
    }
`

export { Container, Banner, Img, Content, Button }