import styled from "styled-components";
import { ReactComponent as edit } from "../../assets/icons/edit.svg"
import { ReactComponent as del } from "../../assets/icons/trash.svg"


const Wrapper = styled.div`
     max-width: 1440px;
     width: 100%;
     margin: 0 auto;
     padding: var(--padding);
     margin-top: 34px;
     `
const Container = styled.div`
    display: flex;
    flex-direction: column;
    gap: 44px;
    border-radius: 3px;
    border: 1px solid #E6E9EC;
    box-shadow: 0px 10px 30px 0px #0D263B0D;
    padding: 30px;
    margin-top: 32px;
`

const Icons = styled.div``

Icons.Edit = styled(edit)`
    margin:16px;
    cursor: pointer;
`

Icons.Delete = styled(del)`
    margin:16px;
    cursor: pointer;
`

const Section = styled.div`
    display: ${({ $grid }) => ($grid ? "grid" : "flex")};
    grid-auto-flow: row;
    grid-template-columns: repeat(auto-fit, minmax(330px, 1fr));
    gap: 20px;
    flex-direction: ${({ $column }) => ($column ? "column" : "row")};
    justify-content: ${({ $column }) => $column && "space-between"};
`

const Button1 = styled.button`
    width: 150px;
    height: 44px;
    background-color: white;
    border: 1px solid #0061DF;
    color: #0061DF;
    cursor: pointer;
    opacity: ${({ disabled }) => disabled && "0.3"};
    cursor: ${({ disabled }) => disabled && "not-allowed"};
`

const ImgWrapper = styled.img`
    width: 150px;
    height: 150px;
    background-color: #C4C4C4;
    border-radius: 3px;
`

export { Container, Wrapper, Icons, Section, Button1, ImgWrapper }