import styled from "styled-components";
import { ReactComponent as icon } from "../../assets/icons/googleIcon.svg"

const Container = styled.div`
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
`

const Content = styled.div`
    width: 580px;
    display: flex;
    flex-direction: column;
    gap: 30px;
    padding: 24px 30px;
    border: 1px solid #E6E9EC;
    box-shadow: 0px 10px 30px 0px #0D263B0D;
`
const GoogleButton = styled.button`
    /* width: 70%; */
    height: 44px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
    background-color: white;
    color: black;
    font-size: 20px;
    border: 1px solid #E6E9EC;
    border-radius: 2px;
    cursor: pointer;
`

const Icon = styled(icon)`
    width: 30px;
`

const Separator = styled.div`
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 18px;
    color: gray;
`

const Line = styled.div`
    height: 1px;
    background-color: #E6E9EC;
    width: 100%;
    max-width: 100%;
`

export { Container, Content, GoogleButton, Icon, Separator, Line }