import React, { useEffect, useState } from 'react'
import { AntTable, BlackButton, Container, Icons, User, Wrapper } from './style'
import { useLocation, useNavigate } from 'react-router-dom';
import useSearch from '../../hooks/useSearch';
import noimg from "../../assets/img/noimg.png"
import Button from "../Generic/Button"
import { useQuery } from '@tanstack/react-query';


function MyProfile() {
  const query = useSearch()
  const navigate = useNavigate()

  const token = localStorage.getItem("token") || ""  
  console.log(token);
  

  const { data, refetch } = useQuery({
    queryKey: ["myHouses"],
    queryFn: () =>
      fetch("https://housing-backend-mhvy.onrender.com/api/houses/me", {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token.trim()}`,
        },
      }).then(res => res.json())
  });


  const onDelete = async (id) => {
    const response = await fetch(`https://housing-backend-mhvy.onrender.com/api/houses/${id}`, {
      method: "DELETE",
      headers: {
        "Authorization": `Bearer ${token}`,
      },
    });

    refetch();
  };

  const onSelect = (id) => {
    navigate(`/properties/${id}`)
  }

  const columns = [
    {
      title: "Listing title",
      render: (data) => <User>
        <User.Img src={
          data.attachments && data.attachments.length > 0
            ? "https://housing-backend-mhvy.onrender.com/" + data.attachments[0].imgPath
            : noimg} />
        <User $column={true}>
          <User $column={true}>
            <span className='subTitle'>{data.name}</span>
            <span className='info'>{data.city}, {data.region} {data.country}</span>
          </User>
          <User $column={true}>
            <del className='info'>${data.price}/mo</del>
            <span className='subTitle'>${data.salePrice}/mo</span>
          </User>
        </User>
        <BlackButton>FOR SALE</BlackButton>
      </User>,
      key: "listingtitle"
    },
    {
      title: "Email",
      render: (data) => <span>{data?.user?.email}</span>,
      key: "email"
    },
    {
      title: "Year Build",
      render: (data) => <span>{data?.houseDetails?.yearBuilt}</span>,
      key: "houseDetails.yearBuilt"
    },
    {
      title: "Price",
      render: (data) => <span>$ {data.price}</span>,
      key: "price"
    },
    {
      title: "Action",
      width: 130,
      render: (data) => {
        return (
          <div>
            <Icons.Edit onClick={(e) => {
              e.stopPropagation()
              navigate(`/myprofile/editHouse/${data._id}`)
            }} />
            <Icons.Delete onClick={(e) => {
              e.stopPropagation()
              onDelete(data._id)
            }
            } />
          </div>
        )
      },
      key: "Action"
    }
  ]

  return (
    <Wrapper>
      <User>
        <div className="title" style={{ textAlign: "start" }}>My properties</div>
        <div style={{ marginLeft: "auto" }}>
          <Button onClick={() => navigate("/myprofile/newHouse")}>Add House</Button>
        </div>
      </User>
      <Container>
        <AntTable
          rowKey={(record) => record._id}
          onRow={(record) => {
            return {
              onClick: () => navigate(`/properties/${record?._id}`)
            }
          }}
          dataSource={data?.houses} columns={columns} />
      </Container>
    </Wrapper>
  )
}

export default MyProfile