import React, { forwardRef } from "react";
import { Container, Wrapper, Icon } from "./style";

const Input = forwardRef(({ type, onChange, width, height, value, placeholder, icon, name, defaultValue, require }, ref) => {
  return (
    <Wrapper>
      {icon && <Icon>{icon}</Icon>}
      <Container 
        ref={ref}
        required={require}
        defaultValue={defaultValue}
        $icon={icon}
        name={name}
        width={width}
        height={height}
        onChange={onChange}
        type={type}
        value={value}
        placeholder={placeholder}
      />
    </Wrapper>
  );
});

export default Input;
