import { Table } from "antd";
import styled from "styled-components";
import { ReactComponent as edit } from "../../assets/icons/edit.svg"
import { ReactComponent as del } from "../../assets/icons/trash.svg"

const Container = styled.div`
    border-radius: 3px;
    border: 1px solid #E6E9EC;
    box-shadow: 0px 10px 30px 0px #0D263B0D;
    padding: 30px;
    margin-top: 32px;
`

const Wrapper = styled.div`
     max-width: 1440px;
     width: 100%;
     margin: 0 auto;
     padding: var(--padding);
     margin-top: 34px;
`

const Icons = styled.div``

Icons.Edit = styled(edit)`
    margin:16px;
    cursor: pointer;
    &:hover path {
        fill: blue !important;
    }
`

Icons.Delete = styled(del)`
    margin:16px;
    cursor: pointer;
    &:hover path {
        fill: red !important;
  }
`

const User = styled.div`
    display: flex;
    flex-direction: ${({ $column }) => ($column ? "column" : "row")};
    justify-content: ${({ $column }) => $column && "space-between"};
`

User.Img = styled.img`
    width: 113px;
    height: 113px;
    margin-right: 16px;
`

const BlackButton = styled.button`
    width: 71px;
    height: 23px;
    background-color: #0D263B;
    border: none;
    border-radius: 3px;
    cursor: pointer;
    color: white;
    font-size: 10px;
    margin-left: auto;
`

const AntTable = Table

export { Container, Wrapper, AntTable, Icons, User, BlackButton }