import { NavLink } from "react-router-dom"
import { Container, Content, Icons, IconWrapper } from "./style"
import img from "../../../assets/img/uy.webp"

function Sidebar() {
  return (
    <Container>
      <IconWrapper>
        <img src={img} alt="img" />Houzing Admin
      </IconWrapper>
      <NavLink to="admin" end><Content><Icons.Pencil/>Dashbord</Content></NavLink>
      <NavLink to="admin/users"><Content><Icons.User/>Users</Content></NavLink>
      <NavLink to="admin/properties"><Content><Icons.Building/>Properties</Content></NavLink>
      <NavLink to="/"><Content.Logout onClick ={() => localStorage.removeItem("token")}><Icons.Logout/>Logout</Content.Logout></NavLink>
    </Container>
  )
}

export default Sidebar