import { Tabs } from "antd";
import Signin from "../Signin";
import SignUp from "../SignUp";
import { Container } from "./style";

function Register() {

    return (
        <Container>
            <Tabs defaultActiveKey="1" items={[
                {
                    key: "1",
                    label: "Sign in",
                    children: <Signin />
                },
                {
                    key: "2",
                    label: "Registration",
                    children: <SignUp />
                },
            ]} />
        </Container>
    );
}

export default Register;
