import React, { useEffect, useState } from 'react'
import Card from '../Card'
import { Container, Filter, Input, Select, Title, Wrapper } from './style'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'

function Properties() {
  const [users, setUsers] = useState()
  const [selectedUser, setSelectedUser] = useState("");
  const queryClient = useQueryClient()
  const { data } = useQuery({
    queryKey: ["properties", selectedUser],
    queryFn: () =>
      fetch(`https://housing-backend-mhvy.onrender.com/api/houses${selectedUser ? `?user=${selectedUser}` : ""}`)
    .then(res => res.json())
  })

  useEffect(() => {
    fetch(`https://housing-backend-mhvy.onrender.com/api/users`)
    .then(res => res.json())
    .then(data => setUsers(data))
  }, [])

  const filteredUsers = users?users.filter(user => user.username != "admin"): []
  
  const { mutate } = useMutation({
    mutationFn: async (id) => {
      const res = await fetch(`https://housing-backend-mhvy.onrender.com/api/houses/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`
        }
      })

      if (!res.ok) {
        throw new Error("Xatolik yuz berdi")
      }
      return res.json()
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["properties"])
    }
  })

  const onDelete = (id) => {
    mutate(id)
  }

  return (
    <Container>
      <Filter>
      <Input placeholder='Search by property name'></Input>
        <Select onChange={(e) => setSelectedUser(e.target.value)}>
        <option value="">All users properties</option>
        {
          filteredUsers?.map(user => {
            return <option value={user._id}>{user.username}</option>
          })
        }
      </Select>
      </Filter>
        <Title>Properties</Title>
      <Wrapper>
        {data?.map((item) => (
          <Card key={item._id} data={item} onDelete={onDelete} />
        ))}
      </Wrapper>
    </Container>
  )
}

export default Properties