import { useState } from "react";
import { Container, Content, GoogleButton, Icon, Line, Separator } from "./style";
import { Input, Button } from "../Generic/"
import { useNavigate } from 'react-router-dom';
import { signInWithPopup } from "firebase/auth";
import { auth, provider } from "../../firebase";

function Signin() {
    const navigate = useNavigate()
    const [body, setBody] = useState({})

    const onSubmit = (e) => {
        e.preventDefault()
        fetch("https://housing-backend-mhvy.onrender.com/api/login", {
            method: "POST",
            body: JSON.stringify(body),
            headers: {
                "Content-Type": "application/json"
            }
        })
            .then(res => res.json())
            .then(data => {
                console.log(data)

                if (data?.token) {
                    localStorage.setItem("id", data.user._id)
                    localStorage.setItem("token", data.token);
                    data.isAdmin ? navigate("/admin") : navigate("/home");
                }
            })
            .catch(err => console.error("Fetch error:", err));
    }


    const onChange = ({ target: { name, value } }) => {
        setBody({ ...body, [name]: value });
    };

    const handleLogin = (e) => {
        e.preventDefault()
        signInWithPopup(auth, provider)
            .then((result) => {
                const user = result.user
                localStorage.setItem("token", user.accessToken)
                localStorage.setItem("name", user.displayName)
                localStorage.setItem("email", user.email)
                navigate("/")
            })
            .catch((error) => {
                console.log("Xatolik:", error);
            })
    }    

    return (
        <Container>
            <form>
                <Content>
                    <p className="subTitle">Sign In</p>
                    <Input require="true" name="username" placeholder="username" onChange={onChange} />
                    <Input require="true" type="password" name="password" placeholder="Password" onChange={onChange} />
                    <Button width="100%" onClick={onSubmit}>Login</Button>
                    <Separator>
                        <Line />
                        or
                        <Line />
                    </Separator>
                    <GoogleButton type="button" onClick={handleLogin}>
                        <Icon/>
                        Continue with Google</GoogleButton>
                </Content>
            </form>
        </Container>
    );
}

export default Signin;
