import React, { useEffect, useState } from 'react'
import { Card, CardsWrapper, Container, Title, Wrapper } from './style'
import Chart from "react-apexcharts";

function Dashboard() {
  const [users, setUsers] = useState()
  const [properties, setProperties] = useState([])


  useEffect(() => {
    fetch("https://housing-backend-mhvy.onrender.com/api/houses")
      .then(res => res.json())
      .then(data => setProperties(data))

    fetch("https://housing-backend-mhvy.onrender.com/api/users")
      .then(res => res.json())
      .then(data => setUsers(data))
  }, [])

  const newUsers = users
    ? users.filter(user => {
      if (!user.createdAt) return false;
      const today = new Date().toISOString().split("T")[0];
      const userDate = new Date(user.createdAt).toISOString().split("T")[0];

      return today === userDate;
    })
    : [];

  const newProperties = properties
    ? properties.filter(property => {
      if (!property.createdAt) return false;
      const today = new Date().toISOString().split("T")[0];
      const propertyDate = new Date(property.createdAt).toISOString().split("T")[0];

      return today === propertyDate;
    })
    : [];


  console.log(newUsers?.length, "newwwwww");


  const options = {
    chart: {
      type: "area",
      height: 450,
    },
    series: [
      {
        name: "Current Month",
        data: [200, 500, 300, 700, 1000, 800, 1200, 1400, 1300, 1600, 1800, 1900, 2500, 2700, 2300, 2600, 3000, 2800, 3100, 3500, 3900, 4200, 4500],
      },
      {
        name: "Past Month",
        data: [100, 200, 150, 300, 400, 350, 500, 600, 550, 700, 800, 900, 950, 1000, 1100, 1200, 1300, 1250, 1400, 1500, 1600, 1700, 1800],
      },
    ],
    xaxis: {
      categories: Array.from({ length: 30 }, (_, i) => i + 1),
    },
    colors: ["#008FFB", "#FF4560"],
    stroke: {
      curve: "smooth",
    },
    fill: {
      type: "gradient",
    },
    legend: {
      position: "top",
    },
  };



  return (
    <Container>
      <Title>Blog Overview</Title>
      <CardsWrapper>
        <Card>
          <Card.Title>
            Users
          </Card.Title>
          <Card.Text>{users?.length - 1}</Card.Text>
        </Card>
        <Card>
          <Card.Title>
            Properties
          </Card.Title>
          <Card.Text>{properties?.length}</Card.Text>
        </Card>
        <Card>
          <Card.Title>
            New Users Today
          </Card.Title>
          <Card.Text>{newUsers?.length}</Card.Text>
        </Card>
        <Card>
          <Card.Title>
            New Properties Today
          </Card.Title>
          <Card.Text>{newProperties?.length}</Card.Text>
        </Card>
      </CardsWrapper>
      <Wrapper>
        <Chart options={options} series={options.series} type="area" height={500} />
      </Wrapper>
    </Container>
  )
}

export default Dashboard