import { useEffect, useRef, useState } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import { Container, Logo, Section, Menu, Wrapper, Link, NavbarWrapper, Login, Hamburger, Modal, XIcon, Icons } from './style';
import { navbar } from '../../utils/Navbar';
import Button from '../Generic/Button';
import Footer from '../Footer';
import { auth } from '../../firebase';

function Navbar() {
  const navigate = useNavigate();
  const [userMenu, setUserMenu] = useState(false);
  const [openMenu, setOpenMenu] = useState(false);
  const menuRef = useRef(null);

  const onClick = () => {
    navigate('/signin');
  };

  const onClickProfile = ({ target: { dataset: { name } } }) => {
    if (name === "logout") {
      localStorage.removeItem("token");
      localStorage.removeItem("name");
      localStorage.removeItem("email");
      auth.signOut()
        .then(() => {
          console.log("Foydalanuvchi tizimdan chiqdi");
        })
        .catch((error) => {
          console.log("Tizimdan chiqish xatosi:", error);
        });
      localStorage.removeItem("id");
      navigate('/home');
    } else {
      navigate(name);
    }
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setUserMenu(false);
      }
    };

    if (userMenu) {
      document.addEventListener('click', handleClickOutside);
    }

    return () => {
      document.removeEventListener('click', handleClickOutside);
    };
  }, [userMenu]);

  return (
    <Container className='navbar'>
      <NavbarWrapper>
        {
          openMenu && <Modal $isOpen={openMenu}>
            <XIcon onClick={() => setOpenMenu(!openMenu)}></XIcon>
            <Modal.Content column="true" style={{ marginTop: '218px' }}>
              <Modal.Item onClick={() => {
                setOpenMenu(false)
                navigate('/home')
              }}>Home</Modal.Item>
              <Modal.Item onClick={() => {
                setOpenMenu(false)
                navigate('/properties')
              }}>Properties</Modal.Item>
              <Modal.Item>Contacts</Modal.Item>
            </Modal.Content>
            <Modal.Content style={{ marginTop: '128px' }}>
              <Icons.Facebook />
              <Icons.Twitter />
              <Icons.Instagram />
              <Icons.Linkedin />
            </Modal.Content>
          </Modal>
        }
        <Wrapper>
          <Section className='hamburger'>
            <Hamburger onClick={() => setOpenMenu(!openMenu)} className='hamburger' />
          </Section>
          <Section onClick={() => navigate('/home')} $logo={true}>
            <Logo />
            <h3>Houzing</h3>
          </Section>
          <Section className='links'>
            {navbar.map(({ path, title, hidden }, index) => (
              !hidden && <Link key={index} className={({ isActive }) => isActive && 'active'} to={path}>{title}</Link>
            ))}
          </Section>
          <Section>
            {localStorage.getItem('token') ? (
              <div ref={menuRef}>
                <Login onClick={() => setUserMenu(!userMenu)} />
                {userMenu && (
                  <Menu>
                    <Menu.Item data-name="myprofile" onClick={onClickProfile}>My profile</Menu.Item>
                    <Menu.Item data-name="favourites" onClick={onClickProfile}>Favourites</Menu.Item>
                    <Menu.Item data-name="logout" onClick={onClickProfile}>Log out</Menu.Item>
                  </Menu>
                )}
              </div>
            ) : (
              <Button onClick={onClick} type='dark'>
                Sign in
              </Button>
            )}
          </Section>
        </Wrapper>
      </NavbarWrapper>
      <div style={{ marginTop: '64px' }}>
        <Outlet />
      </div>
      <Footer />
    </Container>
  );
}

export default Navbar;
