import React from "react";
import useId from "../hooks/useId";
import Favourite from "../pages/Favourite";
import Register from "../pages/Register";
import MyProfile from "../pages/MyProfile";
import AddNewHouse from "../pages/AddNewHouse";
import { Spinner } from "../components/Spinner";
import PrivateRoute from "../pages/PrivateRoute";
const HomePage = React.lazy(() => import('../pages/Home/index'))
const Properties = React.lazy(() => import('../pages/Properties/index'))
const HouseItem = React.lazy(() => import('../pages/HouseItem/index'))

export const navbar = [
    {
        id: useId,
        element: (
            <React.Suspense fallback={<Spinner />}>
                <HomePage />
            </React.Suspense>
        ),
        title: "Home",
        path: "/home",
        private: false,
        hidden: false
    },
    {
        id: useId,
        element: (
            <React.Suspense fallback={<Spinner />}>
                <Properties />
            </React.Suspense>
        ),
        title: "Properties",
        path: "/properties",
        private: false,
        hidden: false
    },
    {
        id: useId,
        element: <PrivateRoute><MyProfile /></PrivateRoute>,
        title: "MyProfile",
        path: "/myprofile",
        private: true,
        hidden: true
    },
    {
        id: useId,
        element: (
            <React.Suspense fallback={<Spinner />}>
                <HouseItem />
            </React.Suspense>
        ),
        title: "Single House",
        path: "/properties/:id",
        private: false,
        hidden: true
    },
    {
        id: useId,
        element: <Register />,
        title: "sign In",
        path: "/signIn",
        private: false,
        hidden: true
    },
    {
        id: useId,
        element: <Favourite />,
        title: "favourite",
        path: "/favourites",
        private: true,
        hidden: true
    },
    {
        id: useId,
        element: <PrivateRoute><AddNewHouse /></PrivateRoute>,
        title: "Add New House",
        path: "/myprofile/newHouse",
        private: true,
        hidden: true
    },
    {
        id: useId,
        element: <PrivateRoute><AddNewHouse /></PrivateRoute>,
        title: "Edit House",
        path: "/myprofile/editHouse/:id",
        private: true,
        hidden: true
    }
]