import styled, { keyframes, css } from "styled-components";
import { ReactComponent as LogoImg } from "../../assets/icons/Vector.svg"
import { ReactComponent as LoginIcon } from "../../assets/icons/login.svg"
import { ReactComponent as HamburgerIcon } from "../../assets/icons/hamburger.svg"
import { ReactComponent as xicon } from "../../assets/icons/x.svg"
import { ReactComponent as Facebook } from "../../assets/icons/facebook.svg";
import { ReactComponent as Twitter } from "../../assets/icons/twitter.svg";
import { ReactComponent as Instagram } from "../../assets/icons/instagram.svg";
import { ReactComponent as Linkedin } from "../../assets/icons/linkedin.svg";

import { NavLink } from "react-router-dom";

const fadeIn = keyframes`
    0% {
        opacity: 0;
        transform: translateY(-20px);
        scale: 0.9;
    }
    50% {
        opacity: 0.5;
        transform: translateY(-10px);
        scale: 0.95;
    }
    100% {
        opacity: 1;
        transform: translateY(0);
        scale: 1;
    }
`;

const OpenMenu = keyframes`
    0% {
        transform: translateX(-100%);
    }
    100% {
        transform: translateX(0);
    }
`;


const Container = styled.div`
    display: flex;
    flex-direction: column;
    justify-content: center;
`

const NavbarWrapper = styled.div`
    width: 100%;
    display: flex;
    justify-content: center;
    background-color: var(--primary-color);
    position: fixed;
    top: 0;
    z-index: 8888;
`

const IconStyle = css`
     width: 36px;
    height: 36px;
    padding: 10px;
    border-radius: 3px;
    margin-top: -10px;
    cursor: pointer;
    transition: 0.3s ease background-color;
    &:hover {
        background-color: #E7EAEC;
    }
    path{
    fill: #0D263B;
}
`

const Wrapper = styled.div`
display: flex;
align-items: center;
justify-content: space-between;
color: #fff;
padding: var(--padding);
height: 64px;
font-size: 16px;
width: 100%;
max-width: 1440px;

@media (max-width: 650px) {
    padding: 0 16px;
}

.hamburger {
    display: none;
    @media (max-width: 650px) {
       display: block; 
    }
}
`

const Section = styled.div`
display: flex;
align-items: center;
cursor: ${({ $logo }) => $logo && 'pointer'};

    .active {
        border-bottom: 2px solid red
    }

    .hamburger {
        display: none;

        @media (max-width: 500px) {
            display: block;
        }
    }

    &.links {
        @media (max-width: 500px) {
            display: none;
        }
    }
`

const Logo = styled(LogoImg)`
    margin-right: 12px;
`

const Login = styled(LoginIcon)`
    cursor: pointer;
`

const Hamburger = styled(HamburgerIcon)`
    cursor: pointer;
`
const XIcon = styled(xicon)`
    cursor: pointer;
    margin: 20px;
    position: absolute;
`

const Icons = styled.div``
Icons.Facebook = styled(Facebook)`
    ${IconStyle}
`
Icons.Twitter = styled(Twitter)`
    ${IconStyle}
`
Icons.Instagram = styled(Instagram)`
    ${IconStyle}
`
Icons.Linkedin = styled(Linkedin)`
    ${IconStyle}
`

const Link = styled(NavLink)`
    text-decoration: none;
    color: #fff;
    margin: 0 32px;
`

const Menu = styled.div`
    width: 177px;
    margin-top: 15px;
    margin-left: -152px;
    position: absolute;
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding: 16px;
    background-color: white;
    border-radius: 3px;
    color: black;
    z-index: 999;
    box-shadow: 0px 0px 15px 0px #0000000F;
    box-shadow: 0px 7px 46px 0px #0000000F;
    box-shadow: 0px 20px 38px 0px #0000000F;
    animation: ${fadeIn} 0.1s ease-in-out;
`

Menu.Item = styled.div`
    font-weight: 400;
    font-size: 14px;
    cursor: pointer;
`

const Modal = styled.div`
    width: 100%;
    height: 100vh;
    background-color: white;
    position: absolute;
    top: 0;
    left: 0;
    z-index: 9999;
    transition: transform 0.3s ease;
    transform: translateX(${({ $isOpen }) => ($isOpen ? "0" : "-100%")});`

Modal.Content = styled.div`
    width: fit-content;
    display: flex;
    align-items: center;
    flex-direction: ${({ column }) => column && "column"};
    gap: 25px;
    margin: auto;
`

Modal.Item = styled.div`
    font-weight: 500;
    font-size: 18px;
    color: #0D263B;
    cursor: pointer;
`

export { Modal, Container, Icons, Wrapper, Menu, Section, Logo, Link, NavbarWrapper, Login, Hamburger, XIcon }