import styled, { keyframes, css } from "styled-components";
import { ReactComponent as Location } from "../../assets/icons/location.svg";
import { ReactComponent as Phone } from "../../assets/icons/phone.svg";
import { ReactComponent as Email } from "../../assets/icons/email.svg";
import { ReactComponent as Maps } from "../../assets/icons/cardMaps.svg";
import { ReactComponent as Facebook } from "../../assets/icons/facebook.svg";
import { ReactComponent as Twitter } from "../../assets/icons/twitter.svg";
import { ReactComponent as Instagram } from "../../assets/icons/instagram.svg";
import { ReactComponent as Linkedin } from "../../assets/icons/linkedin.svg";
import { ReactComponent as Logo } from "../../assets/icons/Vector.svg";
import { ReactComponent as Arrow } from "../../assets/icons/arrow.svg";

const showButton = keyframes`
    0%{
        opacity: 0;
        transform: scale(0.5);
    }
    100%{
        opacity: 1;
        transform: scale(1);
    }
`


const IconStyle = css`
    width: 36px;
    height: 36px;
    padding: 8px;
    border-radius: 3px;
    margin-top: -10px;
    cursor: pointer;
    transition: 0.3s ease background-color;
    &:hover {
        background-color: rgba(255, 255, 255, 0.2);
    }
`

const Container = styled.div`
    position: relative;
    width: 100%;
    height: 432px;
    background-color: #0D263B;
    padding-top: 48px;
    margin-top: 48px;
`

const Content = styled.div`
    width: 235px;
    display: flex;
    flex-direction: column;
    color: white;
`

Content.Title = styled.div`
    font-weight: 600;
    font-size: 16px;
    color: white;
    margin-bottom: 32px;
`

Content.Item = styled.div`
    display: flex;
    align-items: flex-start;
    gap: 21px;
    font-weight: 400;
    font-size: 14px;
    line-height: 20px;
    margin-bottom: 20px;
`

const Wrapper = styled.div`
    width: 100%;
    max-width: 1440px;
    padding: 0 130px;
    margin: auto;
`

const ContentsWrapper = styled.div`
     display: flex;
     justify-content: space-between;
`

const Icons = styled.div``
Icons.Location = styled(Location)`
    margin-bottom: 24px;
    width: 40px;
    height: 48px;
`
Icons.Phone = styled(Phone)``
Icons.Email = styled(Email)``
Icons.Maps = styled(Maps)``
Icons.Facebook = styled(Facebook)`
    ${IconStyle}
`
Icons.Twitter = styled(Twitter)`
    ${IconStyle}
`
Icons.Instagram = styled(Instagram)`
    ${IconStyle}
`
Icons.Linkedin = styled(Linkedin)`
    ${IconStyle}
`
Icons.Logo = styled(Logo)``
Icons.Arrow = styled(Arrow)`
    transform: rotate(90deg);
    path{
        fill: white;
    }
`

const Section = styled.div`
display: flex;
align-items: center;
cursor: pointer;
gap: 8px;
`

const IconsWrapper = styled.div`
    display: flex;
    gap: 37px;
    margin-top: 32px;
`

const Bottom = styled.div`
    width: 100%;
    max-width: 1440px;
    margin: auto;
    display: flex;
    justify-content: space-between;
    border-top: 1px solid #FFFFFF26;
    padding: 16px 130px;
    margin-top: 15px;
    color: white;
`

const Button = styled.button`
    width: 45px;
    height: 45px;
    background-color: #0061DF;
    border: none;
    cursor: pointer;
    position: fixed;
    right: 12px;
    bottom: 12px;
    z-index: 1000;
    display: ${({ $show }) => ($show ? "block" : "none")};
    animation: ${showButton} 0.3s linear;
`

export { Container, Content, Wrapper, Icons, IconsWrapper, ContentsWrapper, Bottom, Section, Button }