import { Container, Content, Details, Icons, Img, Divider } from "./style"
import noimg from "../../assets/img/noimg.png"
import { useMutation } from "@tanstack/react-query"
import { useState } from "react";

function HouseCard({ data, onClick, refreshData }) {
    const { _id, attachments, city, country, address, houseDetails, category, favourite, price } = data
    const [isFavourite, setIsFavourite] = useState(favourite);

    const mutation = useMutation({
        mutationFn: async (id) => {
            const res = await fetch(`https://housing-backend-mhvy.onrender.com/api/houses/addFavourite/${id}?favourite=${!isFavourite}`, {
                method: "PUT",
            });

            if (!res.ok) {
                throw new Error("Failed to update favourite status");
            }

            return res.json();
        },
        onSuccess: () => {
            refreshData();
        },
    });


    const handleFavourite = (e) => {
        e.stopPropagation();
        const prevState = isFavourite;
        setIsFavourite((prev) => !prev);

        mutation.mutate(_id, {
            onSuccess: () => {
                setIsFavourite(prevState);
            }
        });
    };

    return (
        <Container onClick={onClick}>
            {console.log("https://housing-backend-mhvy.onrender.com",attachments[0]?.imgPath)}
            <Img src={`https://housing-backend-mhvy.onrender.com/${attachments[0]?.imgPath}` || noimg}></Img>
            <Content>
                <div className="subTitle">{city} {country}</div>
                <div className="info">{address || 'Quincy St, Brooklyn, NY, USA'} - {category?.name || 'category'}</div>
                <Details>
                    <Details.Item>
                        <Icons.Bed />
                        <div className="info">{houseDetails?.beds || 0} Beds</div>
                    </Details.Item>
                    <Details.Item>
                        <Icons.Bath />
                        <div className="info">{houseDetails?.bath || 0} Baths</div>
                    </Details.Item>
                    <Details.Item>
                        <Icons.Garage />
                        <div className="info">{houseDetails?.garage || 0} Garage</div>
                    </Details.Item>
                    <Details.Item>
                        <Icons.Ruler />
                        <div className="info">{houseDetails?.area || 0} Sq Ft</div>
                    </Details.Item>
                </Details>
            </Content>
            <Divider></Divider>
            <Content $footer={true}>
                <Details.Item $footer={true}>
                    <del><div className="info">{price > 0 && (price/24).toLocaleString()}/mo</div></del>
                    <div className="subTitle">{price > 0 && (price/36).toLocaleString()}/mo</div>
                </Details.Item>
                <Details.Item $row={true}>
                    <Icons.Resize />
                    <Icons.Heart onClick={(e) => handleFavourite(e)} $favourite={isFavourite} />
                </Details.Item>
            </Content>
        </Container>
    );
}

export default HouseCard;
