import styled from "styled-components";
import { Table } from "antd";
import { ReactComponent as del} from "../../../assets/icons/trash.svg"
import { ReactComponent as ban} from "../../../assets/icons/ban.svg"
import { ReactComponent as admin} from "../../../assets/icons/admin.svg"

const Container = styled.div`
    height: calc(100vh - 64px);
    overflow-y: auto;
`

const Content = styled.div`
    width: 95%;
    margin:  auto;
    border-radius: 3px;
    border: 1px solid #E6E9EC;
    box-shadow: 0px 15px 30px 0px #0D263B0D;
    padding: 30px;
`

const Button = styled.button`
    padding: 5px 10px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 5px;
    cursor: pointer;
    background-color: transparent;
    border: none;
    color: ${({ $color }) => $color || "black"};
`

const Trash = styled(del)`
    width: 20px;
    path {
        fill: red !important;
    }
`

const Ban = styled(ban)`
    width: 17px;
    path {
        fill: #ff9800;
    }
`

const Admin = styled(admin)`
    width: 20px;
    path {
        fill: #2196f3 !important;
    }
`

const AntTable = Table

const Title = styled.div`
    width: 95%;
    font-size: 28px;
    font-weight: 600;
    color: rgba(0, 0, 0, 0.5);
    margin: 30px auto;
`


export { Title, AntTable, Container, Content, Button, Trash, Ban, Admin };