import styled from "styled-components";

const Container = styled.div`
    width: 100%;
    height: calc(100vh - 64px);
    overflow-y: auto;
    position: relative;
    /* background-color:rgb(241, 241, 241); */
`

const Wrapper = styled.div`
    width: 95%;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 30px;
    margin: 0 auto;
`
const Filter = styled.div`
    width: 95%;
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 15px 20px;
    border-radius: 12px;
    background: rgb(255, 255, 255);
    box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.1);
    margin: 0 auto;
    position: sticky;
    top: 5px;
    z-index: 9999;
`;

const Input = styled.input`
    flex: 1;
    padding: 12px 15px;
    font-size: 16px;
    border: 1px solid rgba(0, 0, 0, 0.2);
    border-radius: 8px;
    outline: none;
    transition: 0.3s;
    background: #fff;
    
    &:focus {
        border-color: #4A90E2;
        box-shadow: 0px 0px 8px rgba(74, 144, 226, 0.4);
    }
`;

const Select = styled.select`
    padding: 12px 15px;
    font-size: 16px;
    border: 1px solid rgba(0, 0, 0, 0.2);
    border-radius: 8px;
    background: #fff;
    cursor: pointer;
    transition: 0.3s;
    outline: none;
    
    &:hover {
        border-color: #4A90E2;
    }
    
    &:focus {
        border-color: #4A90E2;
        box-shadow: 0px 0px 8px rgba(74, 144, 226, 0.4);
    }
`;

const Title = styled.div`
    width: 95%;
    font-size: 28px;
    font-weight: 600;
    color: rgba(0, 0, 0, 0.5);
    margin: 30px auto;
`


export { Title, Container, Wrapper, Filter, Input, Select }