import { Outlet } from "react-router-dom"
import { Container, Content } from "./style"
import Sidebar from "../Sidebar"
import Navbar from "../Navbar"

function AdminLayout() {
    return (
        <Container>
            <Sidebar />
            <Content>
                <Navbar />
                <Outlet />
            </Content>
        </Container>
    )
}

export default AdminLayout