import styled, { css } from "styled-components";
import { ReactComponent as home } from "../../../assets/icons/house.svg"
import { ReactComponent as search } from "../../../assets/icons/search.svg"
import { ReactComponent as user } from "../../../assets/icons/user2.svg"
import { ReactComponent as setting } from "../../../assets/icons/setting2.svg"
import { ReactComponent as bell } from "../../../assets/icons/bell.svg"

const iconStyle = css`
    width: 20px;
    height: 20px;
    cursor: pointer;
    path {
        fill: rgba(0, 0, 0, 0.3);
    }
`

const Container = styled.div`
    height: 60px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 30px;    
    background-color: white;
    box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.1);
`

const Content = styled.div`
    display: flex;
    gap: 15px;
`

const HouseIcon = styled(home)`
    width: 18px;
    height: 18px;
    cursor: pointer;

    path {
        fill: rgba(0, 0, 0, 0.2);
    }
`

const Icons = styled.div``
Icons.User = styled(user)`
    ${iconStyle}
`

Icons.Setting = styled(setting)`
    ${iconStyle}
`

Icons.Bell = styled(bell)`
    ${iconStyle}
`

Icons.Searchicon = styled(search)`
    width: 13px;
    height: 13px;
    path {
        fill: rgba(0, 0, 0, 0.2);
    }
`

const Input = styled.input`
    border: none;
    outline: none;
    color: rgba(0, 0, 0, 0.5);

    &::placeholder {
        color: rgba(0, 0, 0, 0.5);
    }
`

export { Container, Content, Icons, HouseIcon, Input }