import { Banner, Button, Container, Content, Img } from "./style"
import noimg from "../../../assets/img/house1.png"

function Card({data, onDelete}) {
    
    return (
        <Container>
            <Banner>$200000</Banner>
            <Img src={"https://housing-backend-mhvy.onrender.com/" + data?.attachments[0]?.imgPath} />
            <Content>
                <Content.Title>{data?.name || "hbub"}</Content.Title>
                <Content.Text>{data?.address} - {data?.category?.name}</Content.Text>
                <Content.Text>Created by: {data?.user?.username}</Content.Text>
                <Content.Text>Created at: 12.03.2025</Content.Text>
                <Button onClick={() => onDelete(data?._id)}>DELETE</Button>
            </Content>
        </Container>
    )
}

export default Card