import React, { useEffect, useRef, useState } from 'react';
import { Container, Section, Wrapper, Button1, ImgWrapper } from './style';
import { Input, Button } from '../Generic';
import TextArea from 'antd/es/input/TextArea';
import { Controller, useForm } from 'react-hook-form';
import { useNavigate, useParams } from 'react-router-dom';

function AddHouse() {
  const fileInputRef = useRef(null);
  const [images, setImages] = useState([]);
  const [initialValues, setInitialValues] = useState({});

  const token = localStorage.getItem("token") || "";
  const { id } = useParams();
  const navigate = useNavigate();
  const { register, handleSubmit, control } = useForm();

  useEffect(() => {
    if (id) {
      fetch(`https://housing-backend-mhvy.onrender.com/api/houses/${id}`, {
        headers: {
          Authorization: `Bearer ${token}`
        }
      })
        .then(res => res.json())
        .then(data => setInitialValues(data));
    }
  }, [id, token]);

  const handleClick = (e) => {
    e.preventDefault();
    fileInputRef.current.click();
  };

  const handleFileChange = (event) => {
    const files = Array.from(event.target.files); 
    setImages(prevImages => [...prevImages, ...files]);
  };

  const onSubmit = (data) => {
    const formData = new FormData();

    images.forEach((image) => {
      formData.append("attachments", image);
    });

    Object.keys(data).forEach((key) => {
      formData.append(key, data[key]);
    });

    fetch(`https://housing-backend-mhvy.onrender.com/api/houses/${id || ""}`, {
      method: id ? "PUT" : "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
      body: formData,
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.message === "House added successfully" || data.message === "Uy ma'lumotlari muvaffaqiyatli yangilandi") {
          navigate("/myprofile");
        }
      })
      .catch((error) => console.error("Xatolik:", error));
  };

  return (
    <Wrapper>
      <div className="title" style={{ textAlign: "start" }}>Add new property</div>

      <form onSubmit={handleSubmit(onSubmit)}>
        <Container>
          <div className="subTitle">Contact information</div>
          <Section>
            <Input defaultValue={initialValues?.name} {...register("name")} placeholder="Property title" />
            <Input {...register("type")} placeholder="Type" />
          </Section>
          <Controller
            name="description"
            control={control}
            render={({ field }) => <TextArea {...field} value={initialValues?.description} placeholder="Property Description*" />}
          />
        </Container>

        <Container>
          <div className="subTitle">Additional</div>
          <Section $grid={true}>
            <Input defaultValue={initialValues?.houseDetails?.room} {...register("room")} type="number" placeholder="Rooms" />
            <Input defaultValue={initialValues?.houseDetails?.bath} {...register("bath")} type="number" placeholder="Bath" />
            <Input defaultValue={initialValues?.houseDetails?.beds} {...register("beds")} type="number" placeholder="Beds" />
            <Input defaultValue={initialValues?.houseDetails?.garage} {...register("garage")} type="number" placeholder="Garage" />
            <Input defaultValue={initialValues?.houseDetails?.area} {...register("area")} type="number" step="0.1" placeholder="Area" />
            <Input defaultValue={initialValues?.houseDetails?.yearBuilt} {...register("yearBuilt")} type="number" placeholder="Year build" />
            <Input defaultValue={initialValues?.category?.name} {...register("category")} placeholder="Category" />
            <Input defaultValue={initialValues?.zipCode} {...register("zipCode")} placeholder="Zip code" />
            <Input defaultValue={initialValues?.price} {...register("price")} type="number" placeholder="Price" />
          </Section>
        </Container>

        <Container>
          <div className="subTitle">Location</div>
          <Section $grid={true}>
            <Input defaultValue={initialValues?.region} {...register("region")} placeholder="Region" />
            <Input defaultValue={initialValues?.country} {...register("country")} placeholder="Country" />
            <Input defaultValue={initialValues?.city} {...register("city")} placeholder="City" />
            <Input defaultValue={initialValues?.addres} {...register("address")} placeholder="Address" />
            <Input defaultValue={initialValues?.location?.longitude} {...register("longitude")} type="number" step="0.0001" placeholder="Longitude" />
            <Input defaultValue={initialValues?.location?.latitude} {...register("latitude")} type="number" step="0.0001" placeholder="Latitude" />
          </Section>
        </Container>

        <Container>
          <div className="subTitle">Images</div>
          <Section>
              {images.map((file, index) => (
                <ImgWrapper
                  key={index}
                  src={URL.createObjectURL(file)}
                  alt={`Uploaded ${index}`}
                  style={{ width: "100px", height: "100px", margin: "5px", objectFit: "cover", borderRadius: "5px" }}
                />
              ))}
          </Section>
          <Button1 width="150px" type="light" onClick={handleClick}>
            Upload
          </Button1>
          <input
            id="file-upload"
            type="file"
            multiple
            style={{ display: "none" }}
            ref={fileInputRef}
            onChange={handleFileChange}
          />
        </Container>

        <div style={{ width: "fit-content", marginLeft: "auto", marginTop: "32px" }}>
          <Button width="280px" type="submit">{id ? "Update Property" : "Submit"}</Button>
        </div>
      </form>
    </Wrapper>
  );
}

export default AddHouse;
