import { useState } from "react";
import { Container, Content } from "./style";
import { Input, Button } from "../Generic/"
import { useNavigate } from 'react-router-dom';
import { GoogleButton, Icon, Line, Separator } from "../Signin/style";
import { signInWithPopup } from "firebase/auth";
import { auth, provider } from "../../firebase";

function SignUp() {
    const navigate = useNavigate()
    const [body, setBody] = useState({})

    const onSubmit = () => {
        fetch("https://housing-backend-mhvy.onrender.com/api/register", {
            method: "POST",
            body: JSON.stringify(body),
            headers: {
                "Content-Type": "application/json"
            }
        })
            .then(res => res.json())
            .then(res => {
                if (res.token) {
                    localStorage.setItem("token", res.token)
                    navigate("/home")
                } else {
                    console.log("Registration failed:", res.error);
                }
            })
            .catch(err => console.error("Fetch error:", err));
    }

    const onChange = ({ target: { name, value } }) => {
        setBody({ ...body, [name]: value });
    };

    const handleLogin = () => {
        signInWithPopup(auth, provider)
            .then((result) => {
                const user = result.user
                localStorage.setItem("token", user.accessToken)
                localStorage.setItem("name", user.displayName)
                localStorage.setItem("email", user.email)
                navigate("/")
            })
            .catch((error) => {
                console.log("Xatolik:", error);
            })
    }   


    return (
        <Container>
            <form>
                <Content>
                    <p className="subTitle">Registration</p>
                    <Input require="true" type="text" name="username" placeholder="Username" onChange={onChange} />
                    <Input require="true" type="email" name="email" placeholder="Email" onChange={onChange} />
                    <Input require="true" type="text" name="firstName" placeholder="FirstName" onChange={onChange} />
                    <Input require="true" type="text" name="lastName" placeholder="LastName" onChange={onChange} />
                    <Input require="true" type="password" name="password" placeholder="Password" onChange={onChange} />
                    <Button type="button" width="100%" onClick={onSubmit}>Register</Button>
                    <Separator>
                        <Line />
                        or
                        <Line />
                    </Separator>
                    <GoogleButton type="button" onClick={handleLogin}>
                        <Icon/>
                        Continue with Google</GoogleButton>
                </Content>
            </form>
        </Container>
    );
}

export default SignUp;
